import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import * as THREE from 'three';
import {MeshBVH,acceleratedRaycast} from 'three-mesh-bvh';

// Hashes captured from the approved pre-LOD asset, not generated by the packer.
const approved={
 'tropical-grove':{bytes:2044336,sha:'af89c7717a3300ce38f856a6e6c87bafee5ba39cc86b05b16576549bb89415b0'},
 'planted-cliff':{bytes:1753752,sha:'f5bb6a8623b408c135880065e1486b887fbbc40654c9a236254da610a8946b78'},
};
const summaries=[];
for(const [name,source] of Object.entries(approved)){
 const bytes=await readFile(new URL(`../public/waterslide/${name}.glb`,import.meta.url));
 const jsonLength=bytes.readUInt32LE(12),doc=JSON.parse(bytes.toString('utf8',20,20+jsonLength)),bin=bytes.subarray(28+jsonLength);
 assert.equal(bytes.readUInt32LE(8),bytes.length);
 assert.equal(createHash('sha256').update(bin.subarray(0,source.bytes)).digest('hex'),source.sha,'approved near geometry, UVs, normals and maps remain byte-identical');
 assert.equal(doc.materials.length,1,'both details share the original atlas');
 assert.equal(doc.images.length,3,'no duplicate texture payloads');
 const provenance=JSON.parse(await readFile(new URL(`../public/waterslide/${name}.provenance.json`,import.meta.url)));
 assert.equal(provenance.sha256,createHash('sha256').update(bytes).digest('hex'));
 const attribute=id=>{
  const a=doc.accessors[id],v=doc.bufferViews[a.bufferView],columns={VEC2:2,VEC3:3,SCALAR:1}[a.type];
  const type={5126:Float32Array,5123:Uint16Array,5125:Uint32Array}[a.componentType];
  assert.ok(type&&columns);assert.equal(v.byteStride,undefined);
  const data=bin.subarray((v.byteOffset??0)+(a.byteOffset??0),(v.byteOffset??0)+(a.byteOffset??0)+a.count*columns*type.BYTES_PER_ELEMENT);
  const array=new type(data.buffer.slice(data.byteOffset,data.byteOffset+data.byteLength));
  assert.ok(array.every(Number.isFinite),name+' finite attributes');return new THREE.BufferAttribute(array,columns);
 };
 const models=[0,1].map(lod=>{
  const node=doc.nodes.find(n=>n.name?.endsWith(`LOD${lod}`));assert.ok(node);
  assert.equal(doc.meshes[node.mesh].primitives.length,1);const p=doc.meshes[node.mesh].primitives[0];
  const geometry=new THREE.BufferGeometry();
  for(const [gltf,three] of [['POSITION','position'],['NORMAL','normal'],['TEXCOORD_0','uv']])geometry.setAttribute(three,attribute(p.attributes[gltf]));
  geometry.setIndex(attribute(p.indices));assert.equal(p.material,0);
  assert.ok(geometry.index.array.every(i=>i<geometry.attributes.position.count));
  geometry.computeBoundingBox();geometry.boundsTree=new MeshBVH(geometry);
  const mesh=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({side:THREE.DoubleSide}));mesh.raycast=acceleratedRaycast;mesh.updateMatrixWorld(true);return mesh;
 });
 const [near,far]=models,nearTriangles=near.geometry.index.count/3,farTriangles=far.geometry.index.count/3;
 assert.ok(farTriangles<nearTriangles*.55,'distant geometry has a useful reduction');
 assert.equal(farTriangles,provenance.distanceLod.triangles);
 const bounds=near.geometry.boundingBox,size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3());
 for(const axis of ['x','y','z'])for(const edge of ['min','max'])assert.ok(Math.abs(bounds[edge][axis]-far.geometry.boundingBox[edge][axis])<size[axis]*.03,'distant model keeps authored bounds');
 const silhouette=[];
 for(const elevation of [.15,.65])for(let angle=0;angle<Math.PI*2;angle+=Math.PI/2){
  const span=Math.max(...size.toArray())*.8,camera=new THREE.OrthographicCamera(-span,span,span,-span,.1,100);
  camera.position.copy(center).add(new THREE.Vector3(Math.cos(angle),elevation,Math.sin(angle)).normalize().multiplyScalar(40));camera.lookAt(center);camera.updateMatrixWorld(true);
  const ray=new THREE.Raycaster();ray.firstHitOnly=true;let union=0,changed=0;
  for(let y=0;y<48;y++)for(let x=0;x<48;x++){
   ray.setFromCamera({x:(x+.5)/24-1,y:(y+.5)/24-1},camera);
   const a=ray.intersectObject(near,false).length>0,b=ray.intersectObject(far,false).length>0;
   if(a||b)union++;if(a!==b)changed++;
  }
  const error=changed/union;silhouette.push(error);assert.ok(error<.08,`${name} distant silhouette changed ${(error*100).toFixed(2)}%`);
 }
 summaries.push({name,nearTriangles,farTriangles,maxSilhouetteDifference:Math.max(...silhouette),addedBytes:bytes.length-provenance.distanceLod.preservedBinaryBytes});
 for(const mesh of models){mesh.geometry.dispose();mesh.material.dispose();}
}
console.log(JSON.stringify(summaries,null,2));
console.log('PASS approved close-up bytes, shared maps, finite LOD geometry, bounded silhouettes and provenance.');
